using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class CodexAttentionTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}

 static void Send(string session,string name,DateTime utc){var data=new{protocol="conan-event-v1",@event=name,session=session,utc=utc.ToString("o"),title="测试工作流"};string folder=AssistantLogic.EventDirectory(AppDomain.CurrentDomain.BaseDirectory);Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"conan-event-"+Guid.NewGuid().ToString("N")+".json"),new JavaScriptSerializer().Serialize(data));}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);try{var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);runtime.Config.CodexAlerts=true;var notices=new List<string>();runtime.Notification+=(key,text,row)=>notices.Add(key);DateTime now=DateTime.UtcNow;
 Send("auto-approved","PermissionRequest",now.AddSeconds(-6));Send("auto-approved","PostToolUse",now.AddSeconds(-5));Call(runtime,"ReadEvents");Check(!notices.Any(k=>k.Contains("auto-approved")),"resolved approval in same batch stays quiet");Check(runtime.Codex.Tasks["auto-approved"].Status=="working","latest active state retained");notices.Clear();
 Send("step-result","Stop",now.AddSeconds(-4));Call(runtime,"ReadEvents");Check(notices.Count==0,"intermediate turn return is history only");Check(runtime.Codex.Tasks["step-result"].Status=="ended","turn state retained without declaring task complete");notices.Clear();
 Send("transient","PermissionRequest",DateTime.UtcNow);Call(runtime,"ReadEvents");Check(notices.Count==0,"new approval waits grace period before alert");Send("transient","PreToolUse",DateTime.UtcNow.AddMilliseconds(10));Call(runtime,"ReadEvents");Check(notices.Count==0,"quickly resumed workflow cancels pending alert");notices.Clear();
 Send("genuine","PermissionRequest",now.AddSeconds(-5));Call(runtime,"ReadEvents");Check(notices.Count(k=>k.Contains("genuine"))==1,"genuine unresolved approval alerts once");Call(runtime,"ReadEvents");Check(notices.Count(k=>k.Contains("genuine"))==1,"persistent approval does not repeat each poll");Send("cancelled","Interrupt",DateTime.UtcNow);Call(runtime,"ReadEvents");Check(notices.Any(k=>k.Contains("cancelled")),"real interruption still alerts");var validity=typeof(BubbleMessage).GetField("StillValid");Check(validity!=null,"queued approval bubbles can expire when work resumes");if(validity!=null){bool current=true;var queue=new BubbleQueue();var message=new BubbleMessage{Key="codex:genuine:waiting",Text="等待确认",Notification=true};validity.SetValue(message,new Func<bool>(()=>current));queue.Add(message,0);current=false;queue.Tick(1,false);Check(queue.Current==null,"visible stale approval bubble is dismissed");queue.Add(new BubbleMessage{Key="system:other",Text="其他通知",Notification=true},2);current=true;queue.Add(message,2);current=false;queue.Tick(3,false);Check(queue.Pending==0&&queue.Current.Key=="system:other","pending stale approval removed without losing unrelated notice");queue.Add(message,4);Check(queue.Pending==0,"already resolved approval cannot enter queue");}runtime.Telemetry.Dispose();
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}File.WriteAllText(Path.Combine(args[0],"codex-attention-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_events=true}));return failures==0?0:1;}
}
